create temporary view  valid_keywords_${grass_region_without_quote}  as
select  T1.keyword
,T1.level1_global_be_category_id
,T1.level1_global_be_category
from    search_algo.shopping_guide_fast_rising_keyword T1
where   T1.grass_region = ${grass_region}
  and   T1.grass_date = date_sub(${local_date}, 1)
  and   T1.duration IN ('fast_rising_1d_all', 'fast_rising_7d_all')
  and   T1.keyword not in (
    select  keyword
    from    ${schema}.dwd_sr_data_warehouse_nap_diversity_query_keyword_source_1d
    where   grass_region = ${grass_region}
    and     local_date <= date_sub(${local_date}, 1)	-- 过滤掉之前的搜索词
    group by 1
  )
group by 1,2,3
;

--sql_divide_splitter--
INSERT OVERWRITE TABLE ${schema}.dwd_sr_data_warehouse_nap_diversity_query_keyword_source_1d
partition (grass_region = ${grass_region}, local_date = ${local_date})
select 
*
from valid_keywords_${grass_region_without_quote}
